/**
 * ROBUST MERGE & ENRICHMENT
 * Goal: Combine Base LLM data with LinkedIn Search data
 * and ensure NO duplicates pass through.
 */

function normalizeUrl(url) {
  if (!url) return '';
  try {
    return url.toLowerCase().trim()
      .replace(/^https?:\/\//, '')  // Fixed: Correctly escaped forward slashes
      .replace(/^www\./, '')        // Fixed: Correctly escaped dot
      .replace(/\/$/, '');          // Fixed: Correctly escaped trailing slash
  } catch (e) { return url; }
}

const items = $input.all();

// 1. Map Enrichment Data (from LinkedIn Search Branch)
// These items have 'site_url' (lowercase)
const enrichmentMap = {};
items.forEach(item => {
  if (item.json.hasOwnProperty('site_url')) {
    const key = normalizeUrl(item.json.site_url);
    enrichmentMap[key] = item.json;
  }
});

// 2. Process Base Data (from First LLM Branch)
// These items have 'company_name' and 'Site URL'
const baseItems = items.filter(item => item.json.hasOwnProperty('company_name'));
const uniqueResults = new Map();

baseItems.forEach(baseItem => {
  const baseJson = baseItem.json;
  // Ensure we handle cases where 'Site URL' might be missing
  if (!baseJson['Site URL']) return; 

  const lookupKey = normalizeUrl(baseJson['Site URL']);

  // If we already processed this domain in this batch, skip (Deduplication)
  if (uniqueResults.has(lookupKey)) return;

  const enrichmentData = enrichmentMap[lookupKey];
  const outputJson = { ...baseJson };

  // Default LinkedIn to Unknown if missing
  if (!outputJson.linkedin_profile) outputJson.linkedin_profile = 'Unknown';

  if (enrichmentData) {
    // A. Overwrite Name/Title if LinkedIn search found something better
    if (enrichmentData.decision_maker_name && enrichmentData.decision_maker_name !== 'null') {
      outputJson.decision_maker_name = enrichmentData.decision_maker_name;
    }
    if (enrichmentData.decision_maker_title && enrichmentData.decision_maker_title !== 'null') {
      outputJson.decision_maker_title = enrichmentData.decision_maker_title;
    }

    // B. LinkedIn Profile
    if (enrichmentData.linkedin_profile && enrichmentData.linkedin_profile !== 'null') {
      outputJson.linkedin_profile = enrichmentData.linkedin_profile;
    }

    // C. Email Logic (Combine found emails)
    const newEmail = enrichmentData.contact_email;
    if (newEmail && newEmail !== 'Unknown' && newEmail !== 'null') {
        if (outputJson.contact_email && outputJson.contact_email !== 'Unknown') {
            if (!outputJson.contact_email.includes(newEmail)) {
                outputJson.contact_email = `${outputJson.contact_email}, ${newEmail}`;
            }
        } else {
            outputJson.contact_email = newEmail;
        }
    }
  }

  uniqueResults.set(lookupKey, { json: outputJson });
});

return Array.from(uniqueResults.values());

// Get all items from the previous node
const items = $input.all();

// Loop through all items
for (const item of items) {

  // --- 1. Phone Number Cleaning ---
  const phone = item.json.phone_number;

  // Check if phone exists and is not "Unknown"
  if (phone && phone !== "Unknown") {

    // REGEX EXPLANATION:
    // [^0-9+] means "match any character that is NOT a digit (0-9) or a plus sign (+)"
    // We replace those characters with an empty string.
    // Example: "+609 297.5402" becomes "+6092975402"
    let cleanPhone = phone.replace(/[^0-9+]/g, "");

    // Update the JSON data
    item.json.phone_number = cleanPhone;
  }

  // --- 2. LinkedIn Profile Handling ---
  // Ensure the field exists in the output. 
  // If it's missing, null, or empty, set it to "Unknown".
  if (!item.json.linkedin_profile || item.json.linkedin_profile === "null") {
    item.json.linkedin_profile = "Unknown";
  }
}

return items;

// Map the incoming items to Apify's "startUrls" format
const formattedUrls = items.map(item => {
  return {
    "url": item.json.full_url
  };
});

// Return a single item containing the array
// This ensures the Apify node runs only ONCE for all URLs
return {
  json: {
    startUrls: formattedUrls
  }
};

