/**
 * 🚀 ULTIMATE DORK GENERATOR v2.0 (Google-Safe & Self-Feeding)
 * * FEATURES:
 * 1. "Smart Budgeting" for Query Length (Keeps under Google's 32-word limit).
 * 2. Hybrid Strategy: 
 * - STATIC: Deep market exploration with strict filters.
 * - DYNAMIC: Finds lookalike audiences of the leads you already found.
 * 3. Fallback Safety: Never runs empty.
 */

// --- CONFIGURATION ---
const STATIC_PAGES = 10;      // 5 pages x 10 results = 50 results (Static)
const COMPETITOR_PAGES = 3;  // 3 pages x 10 results = 30 results per competitor
const MAX_COMPETITORS = 5;   // Only process the last 3 competitors to save credits

// --- BLOCKLISTS (Organized by Priority) ---

// 1. TIER A: ABSOLUTE TRASH (Always Block)
// These consume ~11 words. We must always include these.
const tierA_Social = [
  "facebook.com", "twitter.com", "instagram.com", "youtube.com", 
  "linkedin.com", "reddit.com", "tiktok.com", "pinterest.com"
];

// 2. TIER B: DIRECTORIES & MARKETPLACES (Rotate These)
// These are good sources but not "Direct Leads". We block them to find actual company sites.
const tierB_Directories = [
  "capterra.com", "g2.com", "softwareadvice.com", "getapp.com",
  "trustpilot.com", "upwork.com", "fiverr.com", "glassdoor.com",
  "clutch.co", "crunchbase.com"
];

// --- STATIC ANGLES (The "Explorer" Engine) ---
// 20 Unique Angles to rotate through over 5 months
const staticAngles = [
  // High Intent (Pricing/Login)
  '"Amazon PPC" "Software" "Pricing" -"Agency"',
  '"Amazon Bid Optimization" "Platform" "Login"',
  '"Amazon Advertising" "Automation" "Start Free Trial"',
  '"Amazon ACOS" "Dashboard" "Sign up"',

  // Feature Specific
  '"Amazon Dayparting" "Tool" "Features"',
  '"Amazon Keyword Harvesting" "Automation" -"Service"',
  '"Amazon Inventory Forecasting" "Software" "PPC"',
  '"Amazon DSP" "Self-serve" "Platform"',
  '"Amazon Merchandising" "Tool" "Analytics"',

  // Tech & Integration
  '"Powered by Amazon SP-API" "Advertising"',
  '"Integration with Amazon Advertising" "Login"',
  '"Amazon Marketing Stream" "Tool" "Beta"',

  // Competitor Alternatives (The "Vs" Strategy)
  '"Alternatives to Teikametrics" "PPC"',
  '"Better than Helium 10" "Advertising"',
  '"Pacvue competitors" "Software"',
  '"AdBadger vs" "Amazon PPC"',

  // Niche/Persona
  '"Amazon PPC Software" "for Agencies" "White Label"',
  '"Amazon Advertising Tool" "for Aggregators"',
  '"Walmart Connect" "Ad Software" "Amazon"', // Cross-market
  '"Instacart Ads" "Management" "Software"'
];

// --- MASTER COMPETITOR LIST (Fallback) ---
// Used if your Google Sheet is empty or new.
const masterCompetitors = [
  "teikametrics.com",
  "helium10.com",
  "junglescout.com",
  "pacvue.com",
  "perpetua.io"
];

// ============================================================
// ⚙️ PROCESSING LOGIC
// ============================================================

// 1. Extract Domains from Google Sheet Input
const sheetRows = $input.all();
const extractedDomains = [];

for (const row of sheetRows) {
  const data = row.json;
  // Adjust 'Link' or 'Site' matches your actual column name in Google Sheets
  let url = data['Link'] || data['Site'] || data['url']; 

  if (url && typeof url === 'string') {
    try {
      const cleanDomain = url.toLowerCase()
        .trim()
        .replace(/^https?:\/\//, '')
        .replace(/^www\./, '')
        .split('/')[0];

      if (cleanDomain && !cleanDomain.includes('google') && !cleanDomain.includes('amazon')) {
        extractedDomains.push(cleanDomain);
      }
    } catch (e) {}
  }
}

// 2. Select Dynamic Competitors
// If we have sheet data, use the last few found. If not, use Master List.
const uniqueFound = [...new Set(extractedDomains)];
const dynamicSources = uniqueFound.length > 0 ? uniqueFound.slice(-MAX_COMPETITORS) : masterCompetitors.slice(0, MAX_COMPETITORS);

// 3. Build Exclusion Strings (The "Safety" Logic)
const socialBlockStr = tierA_Social.map(d => `-site:${d}`).join(' ');
// We only take the first 6 directories to ensure we stay under the word limit
const directoryBlockStr = tierB_Directories.slice(0, 6).map(d => `-site:${d}`).join(' ');

// Combined Negatives for Static Search (Heaviest Filtering)
const staticNegatives = `${socialBlockStr} ${directoryBlockStr} -"Managed Services" -"Book a Call"`;

// Light Negatives for Competitor Search (To avoid breaking 'related:')
const competitorNegatives = `${socialBlockStr}`;

// 4. Calculate Weekly Rotation
const now = new Date();
const start = new Date(now.getFullYear(), 0, 0);
const diff = now - start;
const oneWeek = 1000 * 60 * 60 * 24 * 7;
const absoluteWeek = Math.floor(diff / oneWeek);

// Pick the angle for this week
const currentAngle = staticAngles[absoluteWeek % staticAngles.length];

// ============================================================
// 📤 GENERATE OUTPUT ITEMS
// ============================================================
const newItems = [];

// --- A. STATIC BATCH (The "Fresh Blood") ---
// This finds completely new companies we don't know yet.
// Logic: Query + Strict Negatives
const staticQuery = `${currentAngle} ${staticNegatives}`;

for (let i = 1; i <= (STATIC_PAGES * 10); i += 10) {
  newItems.push({
    json: {
      start_index: i,
      search_query: staticQuery,
      meta_type: "Static Angle",
      meta_topic: currentAngle,
      meta_week: absoluteWeek
    }
  });
}

// --- B. DYNAMIC BATCH (The "Clone" Engine) ---
// This finds companies similar to the ones you ALREADY found.
// Logic: related:domain.com -site:domain.com + Light Negatives
for (const domain of dynamicSources) {

  const dynamicQuery = `related:${domain} -site:${domain} ${competitorNegatives}`;

  for (let i = 1; i <= (COMPETITOR_PAGES * 10); i += 10) { 
    newItems.push({
      json: {
        start_index: i,
        search_query: dynamicQuery,
        meta_type: "Competitor Lookalike",
        meta_source: domain
      }
    });
  }
}

return newItems;

// Get all data coming from the Merge node
const items = $input.all();

// 1. Create a dictionary (map) to store the site dumps
// Key = URL, Value = Content
const siteDumps = {};

// Helper function to clean URLs (removes trailing '/' for better matching)
// e.g. "google.com/" becomes "google.com"
const normalizeUrl = (url) => {
  if (!url) return '';
  return url.trim().replace(/\/$/, '').toLowerCase();
};

// 2. First Pass: Loop through all items to find the "Scraped" data
items.forEach(item => {
  const data = item.json;

  // Check if this item is a Site Dump (has 'url' and 'content')
  if (data.url && data.content) {
    const cleanKey = normalizeUrl(data.url);
    siteDumps[cleanKey] = data.content;
  }
});

// 3. Second Pass: Loop through items to find "Company" data and enrich it
const result = [];

items.forEach(item => {
  const data = item.json;

  // Check if this item is Company Data (has 'Site URL')
  // We exclude items that are just the raw dumps (which usually don't have 'company_name')
  if (data['Site URL'] && data.company_name) {

    const lookupUrl = normalizeUrl(data['Site URL']);

    // Check if we have a dump for this URL
    if (siteDumps[lookupUrl]) {
      // Add the new field
      data.site_dump = siteDumps[lookupUrl];
    } else {
      // Optional: Add a placeholder if no dump is found
      data.site_dump = "No dump found"; 
    }

    // Add to final result
    result.push(item);
  }
});

return result;
